from __future__ import annotations

import hashlib
import json
import unicodedata

GENESIS = "GENESIS"


def normalize_key(s: str) -> str:
    return unicodedata.normalize("NFC", s)


def canonical_bytes(line: dict) -> bytes:
    return json.dumps(
        line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def line_hash(prev_hash: str, line: dict) -> str:
    emptied = dict(line)
    emptied["hash"] = ""
    emptied["prev_hash"] = ""
    payload = prev_hash.encode("utf-8") + b"|" + canonical_bytes(emptied)
    return hashlib.sha256(payload).hexdigest()

from __future__ import annotations

import os
import tempfile


def read_lines(path):
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    with open(path, "rb") as f:
        data = f.read()
    return data.splitlines()


def write_atomic(path, lines):
    data = b"".join(lines)
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

from __future__ import annotations

import json
import os

from ledgerlock.format import GENESIS, canonical_bytes, line_hash, normalize_key
from ledgerlock.store import read_lines


class ConflictError(Exception):
    """Raised when a mutation targets a key already committed under a different rid."""


class Ledger:
    def __init__(self, path):
        self.path = path

    def append(self, operation):
        op = operation[0]
        key = normalize_key(operation[1])
        if key == "":
            raise ValueError("key must be non-empty after NFC normalization")

        if op == "put":
            value = operation[2]
            rid = operation[3]
            ts = operation[4]
        elif op == "delete":
            value = None
            rid = operation[2]
            ts = operation[3]
        else:
            raise ValueError(f"unknown op: {op!r}")

        prev_hash = self._read_prev_hash()

        line = {"op": op, "key": key, "id": rid, "ts": ts}
        if op == "put":
            line["value"] = value

        digest = line_hash(prev_hash, line)
        line["prev_hash"] = prev_hash
        line["hash"] = digest

        data = canonical_bytes(line) + b"\n"
        with open(self.path, "ab") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())

        return line

    def _read_prev_hash(self):
        try:
            lines = read_lines(self.path)
        except FileNotFoundError:
            return GENESIS
        if not lines:
            return GENESIS
        last = json.loads(lines[-1].decode("utf-8"))
        return last["hash"]

    def verify(self):
        raise NotImplementedError

    def snapshot(self):
        raise NotImplementedError

    def apply_batch(self, operations):
        raise NotImplementedError
